/**
 * Signer Helper Functions
 *
 * Factory functions and adapters for creating `IUmbraSigner` instances from
 * common Solana wallet primitives. Covers in-memory keypairs (for testing and
 * scripting), `@solana/kit` `KeyPairSigner` instances, and browser wallets
 * that implement the Wallet Standard (`@wallet-standard/core`).
 *
 * @since 2.0.0
 * @module solana/signers
 * @packageDocumentation
 */

import {
  generateKeyPairSigner as kitGenerateKeyPairSigner,
  createKeyPairSignerFromBytes,
  signBytes,
  getTransactionEncoder,
  getTransactionDecoder,
  type KeyPairSigner,
  type Address,
  type SignatureBytes,
} from "@solana/kit";

import {
  SolanaSignTransaction,
  SolanaSignMessage,
  type SolanaSignTransactionFeature,
  type SolanaSignMessageFeature,
} from "@solana/wallet-standard-features";

import type { Wallet, WalletAccount } from "@wallet-standard/core";

import type { IUmbraSigner, SignedMessage, SignableTransaction } from "../umbra/interfaces";
import type { SignedTransaction } from "./types";

// ============================================================================================
// Internal Adapters
// ============================================================================================

/**
 * Adapts a `@solana/kit` `KeyPairSigner` to the `IUmbraSigner` interface.
 *
 * `KeyPairSigner` uses the partial-signer pattern — `signTransactions` returns
 * `SignatureDictionary[]` (maps of address → signature) rather than signed transaction
 * objects. This adapter bridges that gap by merging each returned signature dictionary
 * back into the transaction's `signatures` map.
 *
 * `signMessage` uses `signBytes` directly on the CryptoKey to produce a `SignedMessage`
 * with the correct structure, since `KeyPairSigner` only has `signMessages` (plural) which
 * also returns dictionaries.
 */
function convertSolanaKitKeypairSignerToIUmbraSigner(kps: KeyPairSigner): IUmbraSigner {
  return {
    address: kps.address,

    async signTransaction(transaction: SignableTransaction): Promise<SignedTransaction> {
      // Cast required: IUmbraSigner's SignableTransaction does not carry the
      // full generic type parameters that KeyPairSigner.signTransactions expects
      // (lifetime constraint, fee payer, signer list). The runtime values are
      // identical — only the TypeScript generics differ.
      const kitTx = transaction as unknown as Parameters<KeyPairSigner["signTransactions"]>[0][number];
      const [sigDict] = await kps.signTransactions([kitTx]);
      return {
        ...transaction,
        signatures: { ...transaction.signatures, ...sigDict },
      } as unknown as SignedTransaction;
    },

    async signTransactions(
      transactions: readonly SignableTransaction[],
    ): Promise<SignedTransaction[]> {
      // Same cast rationale as signTransaction above.
      const kitTxs = transactions as unknown as Parameters<KeyPairSigner["signTransactions"]>[0];
      const sigDicts = await kps.signTransactions(kitTxs);
      return transactions.map((tx, index) => ({
        ...tx,
        signatures: { ...tx.signatures, ...sigDicts[index] },
      })) as unknown as SignedTransaction[];
    },

    async signMessage(message: Uint8Array): Promise<SignedMessage> {
      const signature = await signBytes(kps.keyPair.privateKey, message);
      return { message, signature, signer: kps.address };
    },
  };
}

/**
 * Adapts a Wallet Standard `WalletAccount` to the `IUmbraSigner` interface.
 *
 * Requires both the `Wallet` (for feature implementations) and the specific `WalletAccount`
 * (the signing key to use). The wallet must support both `"solana:signTransaction"` and
 * `"solana:signMessage"` features — an error is thrown at call time if either is absent.
 *
 * Transaction round-trip: `SignableTransaction` → wire bytes via `getTransactionEncoder`,
 * wallet signs → signed wire bytes, decoded via `getTransactionDecoder` to extract the
 * returned signatures, merged back into the original transaction object (preserving
 * `lifetimeConstraint`).
 */
function convertWalletStandardAccountToIUmbraSigner(
  wallet: Wallet,
  account: WalletAccount,
): IUmbraSigner {
  const walletFeatures = wallet.features as Partial<
    SolanaSignTransactionFeature & SolanaSignMessageFeature
  >;

  const signTxFeature = walletFeatures[SolanaSignTransaction];
  const signMessageFeature = walletFeatures[SolanaSignMessage];

  if (signTxFeature === undefined) {
    throw new Error(
      `Wallet "${wallet.name}" does not support the "${SolanaSignTransaction}" feature`,
    );
  }
  if (signMessageFeature === undefined) {
    throw new Error(`Wallet "${wallet.name}" does not support the "${SolanaSignMessage}" feature`);
  }

  const encoder = getTransactionEncoder();
  const decoder = getTransactionDecoder();

  return {
    address: account.address as Address,

    async signTransaction(transaction: SignableTransaction): Promise<SignedTransaction> {
      // Cast required: @solana/kit's encoder returns a branded ReadonlyUint8Array,
      // but the Wallet Standard signTransaction expects plain Uint8Array.
      // The runtime value is identical.
      const wireBytes = encoder.encode(transaction) as unknown as Uint8Array;
      const [output] = await signTxFeature.signTransaction({ account, transaction: wireBytes });
      const decoded = decoder.decode(output.signedTransaction);
      return {
        ...transaction,
        signatures: { ...transaction.signatures, ...decoded.signatures },
      } as unknown as SignedTransaction;
    },

    async signTransactions(
      transactions: readonly SignableTransaction[],
    ): Promise<SignedTransaction[]> {
      // Same cast rationale as signTransaction above.
      const inputs = transactions.map((tx) => ({
        account,
        transaction: encoder.encode(tx) as unknown as Uint8Array,
      }));
      const outputs = await signTxFeature.signTransaction(...inputs);
      return transactions.map((tx, index) => {
        const decoded = decoder.decode(outputs[index].signedTransaction);
        return {
          ...tx,
          signatures: { ...tx.signatures, ...decoded.signatures },
        } as unknown as SignedTransaction;
      });
    },

    async signMessage(message: Uint8Array): Promise<SignedMessage> {
      const [output] = await signMessageFeature.signMessage({ account, message });
      return {
        message,
        // Cast required: Wallet Standard returns its own signature type,
        // we need @solana/kit's SignatureBytes. Both are 64-byte Uint8Array.
        signature: output.signature as unknown as SignatureBytes,
        signer: account.address as Address,
      };
    },
  };
}

// ============================================================================================
// Keypair Helpers
// ============================================================================================

/**
 * Creates a new random in-memory keypair signer.
 *
 * Generates a fresh Ed25519 keypair using the platform's CSPRNG. The private key
 * is non-extractable by default (Web Crypto API constraint). Use this for tests,
 * CI pipelines, and scripts where the wallet lifecycle is managed by your code.
 *
 * @example
 * ```typescript
 * import { createInMemorySigner, getUmbraClient } from "@umbra-privacy/sdk";
 *
 * const signer = await createInMemorySigner();
 * const client = await getUmbraClient({ signer, network: "devnet", rpcUrl, rpcSubscriptionsUrl });
 * ```
 *
 * @remarks
 * The keypair exists only in memory. It is lost when the process exits or the page
 * refreshes. Only use this for testing or scripts where you control the key lifecycle.
 */
export async function createInMemorySigner(): Promise<IUmbraSigner> {
  const kps = await kitGenerateKeyPairSigner();
  return convertSolanaKitKeypairSignerToIUmbraSigner(kps);
}

/**
 * Creates a signer from raw private key bytes.
 *
 * Accepts either 64-byte combined key material (private key + public key) or a
 * 32-byte seed — `@solana/kit` handles both formats via `createKeyPairSignerFromBytes`.
 *
 * @param bytes - Raw private key bytes (64-byte keypair or 32-byte seed).
 *
 * @example
 * ```typescript
 * import { createSignerFromPrivateKeyBytes, getUmbraClient } from "@umbra-privacy/sdk";
 * import { readFileSync } from "fs";
 *
 * // Load from a Solana CLI JSON key file (array of numbers)
 * const keyFile = JSON.parse(readFileSync("/path/to/keypair.json", "utf8"));
 * const signer = await createSignerFromPrivateKeyBytes(new Uint8Array(keyFile));
 * ```
 */
export async function createSignerFromPrivateKeyBytes(bytes: Uint8Array): Promise<IUmbraSigner> {
  const kps = await createKeyPairSignerFromBytes(bytes);
  return convertSolanaKitKeypairSignerToIUmbraSigner(kps);
}

/**
 * Adapts an existing `@solana/kit` `KeyPairSigner` to `IUmbraSigner`.
 *
 * Use this when you already have a `KeyPairSigner` (e.g., from `generateKeyPairSigner`
 * or `createKeyPairSignerFromBytes`) and want to pass it to `getUmbraClient`.
 *
 * @param kps - A `KeyPairSigner` from `@solana/kit`.
 *
 * @example
 * ```typescript
 * import { generateKeyPairSigner } from "@solana/kit";
 * import { createSignerFromKeyPair, getUmbraClient } from "@umbra-privacy/sdk";
 *
 * const kps = await generateKeyPairSigner();
 * const signer = createSignerFromKeyPair(kps);
 * const client = await getUmbraClient({ signer, network: "devnet", rpcUrl, rpcSubscriptionsUrl });
 * ```
 */
export function createSignerFromKeyPair(kps: KeyPairSigner): IUmbraSigner {
  return convertSolanaKitKeypairSignerToIUmbraSigner(kps);
}

// ============================================================================================
// Wallet-Standard Helpers
// ============================================================================================

/**
 * Creates an `IUmbraSigner` from a Wallet Standard `WalletAccount`.
 *
 * This is the primary adapter for browser wallets (Phantom, Backpack, Solflare, etc.)
 * that implement the Wallet Standard. Obtain `wallet` and `account` via
 * `@wallet-standard/react`'s `useWallets()` hook or `@solana/react`.
 *
 * Both `"solana:signTransaction"` and `"solana:signMessage"` must be present in
 * `wallet.features` — an error is thrown immediately if either is missing.
 *
 * @param wallet - The Wallet Standard `Wallet` object (provides feature implementations).
 * @param account - The specific `WalletAccount` to sign with.
 *
 * @example
 * ```typescript
 * import { useWallet } from "@solana/react"; // or @wallet-standard/react
 * import { createSignerFromWalletAccount, getUmbraClient } from "@umbra-privacy/sdk";
 *
 * function useUmbraClient(rpcUrl: string, rpcSubscriptionsUrl: string) {
 *   const { wallet, account } = useWallet();
 *   const signer = createSignerFromWalletAccount(wallet, account);
 *   return await getUmbraClient({ signer, network: "mainnet-beta", rpcUrl, rpcSubscriptionsUrl });
 * }
 * ```
 */
export function createSignerFromWalletAccount(
  wallet: Wallet,
  account: WalletAccount,
): IUmbraSigner {
  return convertWalletStandardAccountToIUmbraSigner(wallet, account);
}
